package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string = ""
var WsRateEd string = ""
var WsGrossEd string = ""
var WsDeptEd string = ""
var WsGrandEd string = ""

var empFile *os.File
var empReader *bufio.Scanner
var EmpRecVar EmpRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func toDecimalFromDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains only digits, possibly spaces? Input record numeric fields are digits.
	// Remove spaces
	s = strings.ReplaceAll(s, " ", "")
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// Parse as integer
	n, err := decimal.NewFromString(s)
	if err != nil {
		// fallback trim
		return decimal.NewFromInt(0)
	}
	return decimal.New(n.IntPart(), -scale)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatUneditedInt(val int64, digits int) string {
	// zero padded to digits, keep low-order digits on overflow
	s := fmt.Sprintf("%d", val)
	if val < 0 {
		abs := -val
		s2 := fmt.Sprintf("%0*d", digits, abs)
		if len(s2) > digits {
			s2 = s2[len(s2)-digits:]
		}
		return "-" + s2 // not needed
	}
	f := fmt.Sprintf("%0*d", digits, val)
	if len(f) > digits {
		f = f[len(f)-digits:]
	}
	_ = s
	return f
}

func decimalPow10(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func storeDecimalRounded(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := val.Round(scale)
	pow := decimalPow10(intDigits)
	// overflow: keep low-order integer digits: modulo pow
	// For negative numbers, COBOL keeps sign? We handle positive only.
	// Mod for decimals in shopspring: Mod returns remainder
	// Use truncation toward zero for modulo? For positive it's simple.
	if r.GreaterThanOrEqual(pow) || r.LessThan(pow.Neg()) {
		// keep low-order digits: val Mod pow, preserving sign
		// For positive: r.Mod(pow)
		// shopspring Mod: x.Mod(y) = x - y*Truncate(x/y)
		r = r.Mod(pow)
		// Handle negative modulo staying negative; if COBOL negative overflow keeps sign
	}
	// Ensure scale exactly
	return r
}

func storeDecimalTruncate(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := val.Truncate(scale)
	pow := decimalPow10(intDigits)
	if r.GreaterThanOrEqual(pow) || r.LessThan(pow.Neg()) {
		r = r.Mod(pow)
	}
	return r
}

// Edited picture formatting
func formatEdited(val decimal.Decimal, picture string) string {
	// picture like "ZZ9.9" "Z,ZZZ,ZZ9.99"
	dotIdx := strings.Index(picture, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = picture[:dotIdx]
		fracPat = picture[dotIdx+1:]
	} else {
		intPat = picture
		fracPat = ""
	}
	fracDigits := len(fracPat)
	// count integer placeholders
	intDigits := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// round to fracDigits
	rounded := val.Round(int32(fracDigits))
	isNeg := rounded.IsNegative()
	if isNeg {
		rounded = rounded.Neg()
	}
	// Get string representation with exactly fracDigits decimal places
	// Use StringFixed
	fixed := rounded.StringFixed(int32(fracDigits))
	// fixed like "1234.56" or "0.00"
	var intStr, fracStr string
	if dotIdx >= 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
	} else {
		intStr = fixed
		fracStr = ""
	}
	// Remove sign from intStr (already)
	// Overflow truncation for integer part: keep low-order intDigits
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	// Now intStr length == intDigits
	// Build intFormatted with commas
	intFormatted := make([]rune, len(intPat))
	dIdx := 0
	for i, ch := range intPat {
		if ch == ',' {
			intFormatted[i] = ','
		} else {
			// Z or 9
			intFormatted[i] = rune(intStr[dIdx])
			dIdx++
		}
	}
	// Apply Z suppression
	suppressed := true
	for i, ch := range intPat {
		if ch == ',' {
			if suppressed {
				intFormatted[i] = ' '
			} else {
				intFormatted[i] = ','
			}
		} else if ch == 'Z' {
			if suppressed && intFormatted[i] == '0' {
				intFormatted[i] = ' '
			} else {
				suppressed = false
				// keep digit as is (even if '0' after non-zero)
			}
		} else if ch == '9' {
			// always show, ends suppression
			suppressed = false
		}
	}
	intPartResult := string(intFormatted)
	var result string
	if dotIdx >= 0 {
		result = intPartResult + "." + fracStr
	} else {
		result = intPartResult
	}
	if isNeg {
		// For signed pictures would need sign handling; not required here
		result = "-" + result
	}
	// result length should equal picture length
	return result
}

func formatHours(val decimal.Decimal) string {
	return formatEdited(val, "ZZ9.9")
}
func formatRate(val decimal.Decimal) string {
	return formatEdited(val, "ZZ9.99")
}
func formatGross(val decimal.Decimal) string {
	return formatEdited(val, "Z,ZZZ,ZZ9.99")
}
func formatDept(val decimal.Decimal) string {
	return formatEdited(val, "ZZZ,ZZZ,ZZ9.99")
}
func formatGrand(val decimal.Decimal) string {
	return formatEdited(val, "ZZ,ZZZ,ZZZ,ZZ9.99")
}

func mainPara() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		// COBOL OPEN INPUT would error, but we handle empty
		empFile = nil
		empReader = nil
		WsEofFlag = "Y"
	} else {
		empReader = bufio.NewScanner(empFile)
		// allow long lines
		// Scanner default split is ScanLines which strips newline
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	if !isFirstRecord() {
		deptBreakPara()
	}
	if empFile != nil {
		empFile.Close()
	}
	grandPara()
}

func readPara() {
	if empReader == nil {
		WsEofFlag = "Y"
		return
	}
	if empReader.Scan() {
		line := empReader.Text()
		// LINE SEQUENTIAL: record is line without newline; pad with spaces
		if len(line) < 17 {
			line = line + strings.Repeat(" ", 17-len(line))
		} else if len(line) > 17 {
			line = line[:17]
		}
		EmpRecVar.ErId = line[0:5]
		EmpRecVar.ErDept = line[5:8]
		EmpRecVar.ErHours = toDecimalFromDigits(line[8:12], 1)
		EmpRecVar.ErRate = toDecimalFromDigits(line[12:17], 2)
	} else {
		WsEofFlag = "Y"
	}
}

func processPara() {
	if isFirstRecord() {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			deptBreakPara()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	payPara()
	readPara()
}

func payPara() {
	// EVALUATE
	forty := decimal.NewFromInt(40)
	if EmpRecVar.ErHours.GreaterThan(forty) {
		WsRegHours = storeDecimalTruncate(decimal.NewFromInt(40), 3, 1)
		// COMPUTE WS-OT-HOURS = ER-HOURS - 40
		// Implicit move with truncation? ER-HOURS -40 yields decimal, stored into 9(3)V9
		tmp := EmpRecVar.ErHours.Sub(forty)
		WsOtHours = storeDecimalTruncate(tmp, 3, 1)
	} else {
		WsRegHours = storeDecimalTruncate(EmpRecVar.ErHours, 3, 1)
		WsOtHours = storeDecimalTruncate(decimal.NewFromInt(0), 3, 1)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.NewFromInt(15).Shift(-1) // 1.5
	calc := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	WsGross = storeDecimalRounded(calc, 7, 2)

	// ADD WS-GROSS TO WS-DEPT-TOTAL (truncated)
	WsDeptTotal = storeDecimalTruncate(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = WsDeptCount + 1
	// overflow for 9(3): keep low 3 digits
	if WsDeptCount >= 1000 {
		WsDeptCount = WsDeptCount % 1000
	}
	WsGrandTotal = storeDecimalTruncate(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = WsGrandCount + 1
	if WsGrandCount >= 100000 {
		WsGrandCount = WsGrandCount % 100000
	}

	WsHoursEd = formatHours(EmpRecVar.ErHours)
	WsRateEd = formatRate(EmpRecVar.ErRate)
	WsGrossEd = formatGross(WsGross)
	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func deptBreakPara() {
	WsDeptEd = formatDept(WsDeptTotal)
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	countStr := formatUneditedInt(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func grandPara() {
	WsGrandEd = formatGrand(WsGrandTotal)
	countStr := formatUneditedInt(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	mainPara()
}
